questionvariables.text:
/* Select a reference angle */
ref_index: rand(3);
ref_list: [30,45,60];
ref_angle: ref_list[ref_index+1];

/* Select a quadrant: 1, 2, 3 or 4 (Quadrant IV added) */
quadrant: 1 + rand(4);
quadnames: ["I", "II", "III", "IV"];
quadname: quadnames[quadrant];

/* Construct the angle */
theta: if quadrant=1 then ref_angle
       else if quadrant=2 then 180-ref_angle
       else if quadrant=3 then 180+ref_angle
       else 360-ref_angle;

/* Calculate sine, cosine and tangent */
sin_theta: sin(theta*%pi/180);
cos_theta: cos(theta*%pi/180);
tan_theta: ratsimp(sin_theta/cos_theta);
/* Values for the reference angle (no signs), used in the worked solution */
sin_ref: sin(ref_angle*%pi/180);
cos_ref: cos(ref_angle*%pi/180);
/* Sign of tan: positive in Quadrants I and III */
tsign: if quadrant=1 or quadrant=3 then 1 else -1;

/* Possible student mistakes */
tan_neg: -tan_theta;      /* wrong sign */
tan_recip: 1/tan_theta;   /* cos/sin instead of sin/cos */
